"""	/** Deletes every access and refresh token of a client, for all users. */
	async revokeAllTokensForClient(clientId: string): Promise<void> {
		await Promise.all([
			this.accessTokenRepository.deleteByClientId(clientId),
			this.refreshTokenRepository.deleteByClientId(clientId),
		]);
	}

	/**
	 * Counts unexpired access tokens per grant, keyed by `${clientId}:${userId}`.
	 * Access token rows carry no expiry, so read `exp` from the JWT payload.
	 * The signature is not checked: the rows were minted by this server.
	 */
	async countActiveAccessTokensByGrant(clientIds: string[]): Promise<Map<string, number>> {
		const rows = await this.accessTokenRepository.findTokensByClientIds(clientIds);
		const nowSeconds = Math.floor(Date.now() / 1000);
		const counts = new Map<string, number>();
		for (const { token, clientId, userId } of rows) {
			const payload = this.jwtService.decodeUnverifiedWithHeader(token)?.payload;
			const exp =
				payload && typeof payload === 'object' && typeof payload.exp === 'number'
					? payload.exp
					: undefined;
			if (exp === undefined || exp <= nowSeconds) continue;
			const key = `${clientId}:${userId}`;
			counts.set(key, (counts.get(key) ?? 0) + 1);
		}
		return counts;
	}

	async revokeAccessToken(token""")

